function group(p){const color=b.get(p),stones=new Set([p]),lib=new Set(),stack=[p];while(stack.length){for(const q of nb(stack.pop()))if(b.get(q)===".")lib.add(q);else if(b.get(q)===color&&!stones.has(q)){stones.add(q);stack.push(q)}}return {stones:[...stones],lib:[...lib]}}
let caps={B:0,W:0},prev="",beforePrev="",events=[];for(const [i,m] of load("moves").entries()){const state=[...b.values()].join("");if(m.p!=="pass"){if(b.get(m.p)!==".")throw Error("occupied"+i);b.set(m.p,m.c==="B"?"X":"O");let captured=[];for(const q of nb(m.p))if(b.get(q)!=="."&&b.get(q)!==b.get(m.p)){const g=group(q);if(!g.lib.length){for(const p of g.stones){captured.push(p);b.set(p,".")}}}if(!group(m.p).lib.length)throw Error("suicide"+i);if([...b.values()].join("")===beforePrev)throw Error("ko"+i);caps[m.c]+=captured.length;if(captured.length)events.push({move:i+1,c:m.c,p:m.p,captured});}beforePrev=state}
const actual=new Map();for(const line of load("last").split("\n")){const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,x)=>actual.set(cols[x]+m[1],v))}
if([...b].some(([p,v])=>actual.get(p)!==v))throw Error("board mismatch");
const seen=new Set(),regions=[];for(const[p,v]of b)if(v==="."&&!seen.has(p)){const pts=[],border=new Set(),stack=[p];seen.add(p);while(stack.length){const q=stack.pop();pts.push(q);for(const r of nb(q))if(b.get(r)==="."){if(!seen.has(r)){seen.add(r);stack.push(r)}}else border.add(b.get(r))}regions.push({points:pts.sort(),count:pts.length,border:[...border]})}
text({moves:load("moves").length,placements:load("moves").filter(m=>m.p!=="pass").length,caps,events,counts:{B:[...b.values()].filter(v=>v==="X").length,W:[...b.values()].filter(v=>v==="O").length},regions,match:true});store("verification",{caps,events,regions});
